function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 10000) return 'nums needs 1 to 10^4 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1e9 || v > 1e9)) return 'Each value is a whole number from -10^9 to 10^9.';
  return null;
}

