function nextGreaterElements(nums) {
  const n = nums.length;
  const answer = new Array(n).fill(-1);
  const stack = [];

  for (let i = 0; i < 2 * n; i++) {
    const value = nums[i % n];
    while (stack.length > 0 && nums[stack[stack.length - 1]] < value) {
      const index = stack.pop();
      answer[index] = value;
    }
    if (i < n) {
      stack.push(i);
    }
  }
  return answer;
}

