function nextGreaterElements(nums) {
  // For each index, look at the next n - 1 positions around the ring.
  const n = nums.length;
  return nums.map((x, i) => {
    for (let step = 1; step < n; step++) {
      const candidate = nums[(i + step) % n];
      if (candidate > x) return candidate;
    }
