function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'large') {
    const n = 2000;
    const span = rand() < 0.5 ? 1e9 : 50;
    const shape = pick(3);
    // 0: random values, 1: mostly falling with noise (long stacks), 2: rising then wrapping.
    return [Array.from({ length: n }, (_, i) => {
      if (shape === 1) return Math.max(-1e9, Math.min(1e9, Math.round(span * (1 - (2 * i) / n)) + pick(3)));
      if (shape === 2) return Math.max(-1e9, Math.min(1e9, Math.round(span * ((2 * ((i + 700) % n)) / n - 1))));
      return pick(2 * span + 1) - span;
    })];
  }
  const n = 1 + pick(10);
  const style = pick(4);
  const span = style === 0 ? 3 : style === 1 ? 10 : 1e9;
  return [Array.from({ length: n }, () => (style === 3 && rand() < 0.5 ? (rand() < 0.5 ? -1e9 : 1e9) : pick(2 * span + 1) - span))];
